<?php require 'includes/auth.php';$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT p.*,sp.shop_name,sp.description shop_description,sp.location,c.name category,u.name seller_name FROM products p JOIN seller_profiles sp ON p.seller_id=sp.id JOIN users u ON sp.user_id=u.id JOIN categories c ON p.category_id=c.id WHERE p.id=? AND p.is_available=1 AND sp.approval_status='approved'");$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Product not found');}
if($_SERVER['REQUEST_METHOD']==='POST'){require_login();verify_csrf();if(user()['role']!=='buyer'){flash('error','Only buyer accounts can add items to a cart.');redirect('product.php?id='.$id);} $qty=(float)post('quantity');if($qty<$p['min_quantity']||$qty>$p['stock']){flash('error','Choose a quantity between '.e($p['min_quantity']).' and '.e($p['stock']).' kg.');}else{$pdo=db();$pdo->prepare('INSERT INTO carts(user_id) VALUES(?) ON DUPLICATE KEY UPDATE user_id=user_id')->execute([user()['id']]);$cart=$pdo->prepare('SELECT id FROM carts WHERE user_id=?');$cart->execute([user()['id']]);$cartId=$cart->fetchColumn();$pdo->prepare('INSERT INTO cart_items(cart_id,product_id,quantity) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantity=LEAST(quantity+VALUES(quantity),?)')->execute([$cartId,$id,$qty,$p['stock']]);flash('success','Added to your cart.');redirect('cart.php');}}
$pageTitle=$p['name'];require 'includes/header.php';?>
<div class="product-detail"><div class="detail-image"><?php if($p['image_path']):?><img src="<?=url($p['image_path'])?>" alt="<?=e($p['name'])?>"><?php else:?>🐟<?php endif;?></div><div><p class="eyebrow"><?=e($p['category'])?></p><h1><?=e($p['name'])?></h1><p class="detail-price">₹<?=number_format($p['price'],2)?> <small>per kg</small></p><p><?=nl2br(e($p['description']))?></p><div class="freshness">✓ <?=e($p['freshness_info']?:'Fresh and ready to order')?> · <?=e($p['stock'])?> kg available</div><form method="post" class="add-cart"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Quantity (kg)<input type="number" step="0.5" min="<?=$p['min_quantity']?>" max="<?=$p['stock']?>" name="quantity" value="<?=$p['min_quantity']?>"></label><button <?=!$p['stock']?'disabled':''?>>Add to cart</button></form><div class="shop-box"><strong>Sold by <?=e($p['shop_name'])?></strong><p><?=e($p['shop_description'])?> · <?=e($p['location'])?></p></div></div></div><?php require 'includes/footer.php'; ?>
